const moveTicket = `-- name: MoveTicket :one
UPDATE ticket SET
   sort_key  = $1,
   staged_at = CASE WHEN $2::boolean THEN $3 ELSE staged_at END,
   parent_id = CASE WHEN $4::boolean THEN NULL ELSE parent_id END,
   version   = version + 1
 WHERE project_id = $5 AND id = $6
RETURNING seq, sort_key, staged_at, version
`

type MoveTicketParams struct {
	SortKey     pgtype.Text
	ChangeStage bool
	StagedAt    pgtype.Timestamptz
	Unparent    bool
	ProjectID   string
	ID          string
}

type MoveTicketRow struct {
	Seq      int32
	SortKey  pgtype.Text
	StagedAt pgtype.Timestamptz
	Version  int32
}

// MoveTicket は動かした1件の sort_key・段・親を書き、version を +1 する（9.4）。
//
// **段（staged_at）と親（parent_id）を位置と同じ文で書く**（9.4.1 / 9.4.2）。
// どちらもドラッグ&ドロップの1操作で位置と同時に決まるため、文を分けると
// 途中で失敗したときに「段は移ったが位置は末尾」「ルートにはなったが位置は
// 元のまま」という中途半端な状態が残る。
//
// change_stage が false のとき staged_at は現在値のままで、並べ替えだけを行う
// （リクエストで staged を省略した場合）。unparent も同じで、false なら
// parent_id を触らない。
//
// **@unparent は「ルートにする」だけを表す。** move が受け取る parent_seq は
// null に限られる（9.4.2）ので、親を付け替える経路はここに無い——それは
// PATCH（9.5.2）の仕事である。
func (q *Queries) MoveTicket(ctx context.Context, arg MoveTicketParams) (MoveTicketRow, error) {
	row := q.db.QueryRow(ctx, moveTicket,
		arg.SortKey,
		arg.ChangeStage,
		arg.StagedAt,
		arg.Unparent,
		arg.ProjectID,
		arg.ID,
	)
	var i MoveTicketRow
	err := row.Scan(
		&i.Seq,
		&i.SortKey,
		&i.StagedAt,
		&i.Version,
	)
	return i, err
}

const nextTicketSeq = `-- name: NextTicketSeq :one

UPDATE project_counter
   SET last_ticket_seq = last_ticket_seq + 1
 WHERE project_id = $1
RETURNING last_ticket_seq
`

// ── 作成（ApiDesign.md 9.3）─────────────────────────────────
// NextTicketSeq は DbDesign.md 6.4.1 の1文。行ロックと採番が同時に完了する。
//
// **シーケンスを使わない。** トランザクションが巻き戻っても値を消費するため
// 欠番が出る。チケット番号は人が読む識別子であり、my-app-31 の次が my-app-33
// になるのは望ましくない（同 6.4.1）。
func (q *Queries) NextTicketSeq(ctx context.Context, projectID string) (int32, error) {
	row := q.db.QueryRow(ctx, nextTicketSeq, projectID)
	var last_ticket_seq int32
	err := row.Scan(&last_ticket_seq)
	return last_ticket_seq, err
}

const resolveInitialStatusKey = `-- name: ResolveInitialStatusKey :one
SELECT ws.key
  FROM workflow_status ws
  JOIN project p ON p.workflow_id = ws.workflow_id
 WHERE p.id = $1
 ORDER BY (ws.category = 'todo') DESC, ws.sort_order
 LIMIT 1
`

// ResolveInitialStatusKey は 9.3 の「category='todo' かつ sort_order 最小。
// 該当が無ければ sort_order 最小」をそのまま1文で表す。
//
// 初期ステータスをリクエストで指定させないのは、ワークフローの入口が
// workflow_transition に定義されておらず、任意のステータスで作成できると
// 9.6 の遷移検証を素通りできてしまうためである（9.3）。
func (q *Queries) ResolveInitialStatusKey(ctx context.Context, projectID string) (string, error) {
	row := q.db.QueryRow(ctx, resolveInitialStatusKey, projectID)
	var key string
	err := row.Scan(&key)
	return key, err
}

