const updateTicket = `-- name: UpdateTicket :execrows

UPDATE ticket SET
  type           = COALESCE($1, type),
  title          = COALESCE($2, title),
  body_md        = CASE WHEN $3::boolean        THEN $4        ELSE body_md END,
  priority       = CASE WHEN $5::boolean       THEN $6       ELSE priority END,
  assignee_id    = CASE WHEN $7::boolean    THEN $8    ELSE assignee_id END,
  working_agent_id = CASE WHEN $9::boolean THEN $10 ELSE working_agent_id END,
  parent_id      = CASE WHEN $11::boolean      THEN $12      ELSE parent_id END,
  -- sprint_id は 9.5.2 から外した（pb-6）。スプリントの開始・終了だけが動かす
  -- （sprint.sql の SetTicketsSprintID）。DbDesign.md 6.9.1。
  estimate_point = CASE WHEN $13::boolean THEN $14 ELSE estimate_point END,
  estimate_hours = CASE WHEN $15::boolean THEN $16 ELSE estimate_hours END,
  actual_hours   = CASE WHEN $17::boolean   THEN $18   ELSE actual_hours END,
  start_date     = CASE WHEN $19::boolean     THEN $20     ELSE start_date END,
  due_date       = CASE WHEN $21::boolean       THEN $22       ELSE due_date END,
  -- 9.5.2 で開けた4項目（手順27）。**execution_mode と scope は NOT NULL** なので
  -- COALESCE で足りる（null を送れば 422 で先に落ちる）。readiness と
  -- readiness_note は null が「未判定へ戻す」を表すので _set の形が要る。
  execution_mode = COALESCE($23, execution_mode),
  readiness      = CASE WHEN $24::boolean      THEN $25      ELSE readiness END,
  readiness_note = CASE WHEN $26::boolean THEN $27 ELSE readiness_note END,
  scope          = COALESCE($28, scope),
  version        = version + 1
WHERE project_id = $29 AND seq = $30 AND version = $31
`

type UpdateTicketParams struct {
	Type              pgtype.Text
	Title             pgtype.Text
	BodyMdSet         bool
	BodyMd            pgtype.Text
	PrioritySet       bool
	Priority          pgtype.Text
	AssigneeIDSet     bool
	AssigneeID        pgtype.Text
	WorkingAgentIDSet bool
	WorkingAgentID    pgtype.Text
	ParentIDSet       bool
	ParentID          pgtype.Text
	EstimatePointSet  bool
	EstimatePoint     pgtype.Float8
	EstimateHoursSet  bool
	EstimateHours     pgtype.Float8
	ActualHoursSet    bool
	ActualHours       pgtype.Float8
	StartDateSet      bool
	StartDate         pgtype.Date
	DueDateSet        bool
	DueDate           pgtype.Date
	ExecutionMode     pgtype.Text
	ReadinessSet      bool
	Readiness         pgtype.Text
	ReadinessNoteSet  bool
	ReadinessNote     pgtype.Text
	Scope             []byte
	ProjectID         string
	Seq               int32
	Version           int32
}

// ── 更新・削除・遷移（ApiDesign.md 9.5.2 / 9.5.3 / 9.6。手順17a）──────
// UpdateTicket は 9.5.2 の部分更新。**送られたフィールドだけを更新する。**
//
// **2つの書き方を使い分けている**（project.sql の UpdateProject と同じ形）。
//
//	NOT NULL の列（type / title）  COALESCE(sqlc.narg(…), 現在値)
//	NULL にできる列               CASE WHEN @…_set THEN sqlc.narg(…) ELSE 現在値 END
//
// COALESCE では「NULL を送って空にする」を表せない。assignee_id を外す・親を
// 外す・期限を消すはいずれも 9.5.2 が認めている操作なので、_set のフラグで
// 「送られていない」と「NULL が送られた」を区別する。
//
// **status_key / closed_at / sort_key / staged_at は含めない**（9.5.2）。
// 前2つは 9.6 の遷移、後2つは 9.4 の move が書く。
//
// **working_agent_id はここにも 9.6 にも書き込み口がある**（手順26b）。この文が
// 受けるのは人の操作（消す・差し替える。ApiDesign.md 9.5.2）で、エージェント自身の
// 宣言は SetTicketWorkingAgent が別に行う——あちらは遷移の副作用なので version を
// 動かさず、If-Match の照合も持たない。
//
// **updated_at はトリガが動かす**（trg_ticket_updated。DbDesign.md 6.6）。
// タグだけを付け外しした場合もこの文を通るので、9.2.5 の ETag が必ず変わる。
func (q *Queries) UpdateTicket(ctx context.Context, arg UpdateTicketParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateTicket,
		arg.Type,
		arg.Title,
		arg.BodyMdSet,
		arg.BodyMd,
		arg.PrioritySet,
		arg.Priority,
		arg.AssigneeIDSet,
		arg.AssigneeID,
		arg.WorkingAgentIDSet,
		arg.WorkingAgentID,
		arg.ParentIDSet,
		arg.ParentID,
		arg.EstimatePointSet,
		arg.EstimatePoint,
		arg.EstimateHoursSet,
		arg.EstimateHours,
		arg.ActualHoursSet,
		arg.ActualHours,
		arg.StartDateSet,
		arg.StartDate,
		arg.DueDateSet,
		arg.DueDate,
		arg.ExecutionMode,
		arg.ReadinessSet,
		arg.Readiness,
		arg.ReadinessNoteSet,
		arg.ReadinessNote,
		arg.Scope,
		arg.ProjectID,
		arg.Seq,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
